CREATE TABLE IF NOT EXISTS "student_certificate_templates" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "description" TEXT NOT NULL DEFAULT '',
  "title" TEXT NOT NULL DEFAULT '荣誉证书',
  "orientation" TEXT NOT NULL DEFAULT 'LANDSCAPE',
  "backgroundPath" TEXT,
  "backgroundKey" TEXT,
  "slots" JSONB NOT NULL,
  "isActive" BOOLEAN NOT NULL DEFAULT false,
  "sortOrder" INTEGER NOT NULL DEFAULT 0,
  "archivedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "student_certificate_templates_pkey" PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "student_certificate_templates_isActive_archivedAt_sortOrder_idx" ON "student_certificate_templates"("isActive", "archivedAt", "sortOrder");
ALTER TABLE "student_certificate_records" ADD COLUMN IF NOT EXISTS "orientation" TEXT NOT NULL DEFAULT 'LANDSCAPE';
